code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    for rr, cc, sr, sc in ((r-dr, c-dc, -dr, -dc), (nr+dr, nc+dc, dr, dc)):
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                            out[rr][cc] = color
                            rr += sr
                            cc += sc
    return out
'''
